import (
	"fmt"
	"math"
)

func ParseTrinary(arg string) (int64, error) {
	var result int64
	for _, c := range arg {
		var digit int64
		switch c {
		case '0':
			digit = 0
		case '1':
			digit = 1
		case '2':
			digit = 2
		default:
			return 0, fmt.Errorf("invalid trinary digit %q in %q", c, arg)
		}
		if result > (math.MaxInt64-digit)/3 {
			return 0, fmt.Errorf("trinary value %q overflows int64", arg)
		}
		result = result*3 + digit
	}
	if arg == "" {
		return 0, fmt.Errorf("empty trinary string")
	}
	return result, nil
}
"}

